const $=s=>document.querySelector(s);
$('#bottom-saved').onclick=()=>{onlySaved=!onlySaved;render(true);$('#bottom-saved').setAttribute('aria-pressed',onlySaved);$('#main').scrollIntoView()};document.querySelectorAll('.bottom-nav a').forEach(a=>a.addEventListener('click',()=>{onlySaved=false;category='Tutte';render(true);$('#bottom-saved').setAttribute('aria-pressed','false')}));let edition,category='Tutte',onlySaved=false,lastFocus;
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');let activeTransition,readerAnimation,closingReader=false;

