function actions(a){const box=el('div',null,'actions');box.append(button('Leggi approfondimento ↗',()=>open(a),'read'));const b=button(saved.has(a.id)?'Salvata ✓':'Salva +',()=>{saved.has(a.id)?saved.delete(a.id):saved.add(a.id);storage.set('saved',[...saved]);render(true);$('#status').textContent=saved.has(a.id)?'Storia salvata.':'Storia rimossa dai salvati.'},'bookmark');b.setAttribute('aria-label',`${saved.has(a.id)?'Rimuovi dai salvati':'Salva'}: ${a.title}`);b.setAttribute('aria-pressed',saved.has(a.id));box.append(b);return box}
function match(a){return(category==='Tutte'||a.category===category)&&(!onlySaved||saved.has(a.id))}function render(motion=false){
 if(motion&&!reducedMotion.matches&&document.startViewTransition){activeTransition?.skipTransition();const t=document.startViewTransition(()=>render());activeTransition=t;t.ready.catch(()=>{});t.finished.catch(()=>{}).finally(()=>{if(activeTransition===t)activeTransition=null});return;}
 const focus=document.activeElement?.getAttribute('aria-label');const nav=$('#categories');if(!nav.children.length)categories.forEach(c=>{const b=button(c,()=>{if(category===c)return;category=c;render(true)});nav.append(b)});[...nav.children].forEach((b,i)=>b.setAttribute('aria-pressed',categories[i]===category));$('#count').textContent=saved.size;$('#saved').setAttribute('aria-pressed',onlySaved);$('#bottom-saved').setAttribute('aria-pressed',onlySaved);let total=0;
for(const [key,target] of [['essentialIds','#essentials'],['leadIds','#leads'],['compactIds','#compact']]){const container=$(target);container.replaceChildren();edition[key].forEach((id,i)=>{const a=edition.articles.find(x=>x.id===id);if(!a||!match(a))return;total++;if(key==='essentialIds'){const e=el('div',null,'essential');e.style.viewTransitionName='essential-'+a.id;e.append(el('span',String(i+1).padStart(2,'0'),'number'),button(a.title,()=>open(a)));container.append(e);return}const e=el('article',null,key==='leadIds'?'story':'small-story');e.style.viewTransitionName='story-'+a.id;if(a.image)e.append(photo(a));const text=el('div');text.append(el('span',badge(a),'tag'),el('h3',a.title),el('p',a.summary),actions(a));e.append(text);container.append(e)})}$('#empty').hidden=total!==0;$('#essential-section').hidden=!$('#essentials').children.length;$('#lead-count').textContent=String($('#leads').children.length).padStart(2,'0')+' / STORIE';if(focus){const target=[...document.querySelectorAll('[aria-label]')].find(e=>e.getAttribute('aria-label')===focus);target?.focus({preventScroll:true})}if(motion&&!reducedMotion.matches&&!document.startViewTransition){document.querySelectorAll('.story,.small-story').forEach((e,i)=>e.animate([{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:200,delay:Math.min(i*20,80),easing:'cubic-bezier(.2,.8,.2,1)'}))}}
function open(a){closingReader=false;readerAnimation?.cancel();lastFocus=document.activeElement;const c=$('#reader-content');const title=el('h2',a.title);title.id='reader-title';c.replaceChildren(el('span',badge(a),'tag'),title);if(a.image)c.append(photo(a));a.body.forEach(p=>c.append(el('p',p)));c.append(el('p',(a.dateKind==='event'?'Data evento: ':'Pubblicato: ')+date(a.publishedAt),'meta'));if(a.verifiedAt)c.append(el('p','Verificato: '+date(a.verifiedAt)+(a.status==='archive'?'. Contenuto di archivio.':'. Fonte accessibile senza abbonamento al controllo.'),'meta'));if(a.source){const link=el('a','Apri la fonte gratuita · '+a.source.name);link.href=a.source.url;link.target='_blank';link.rel='noopener noreferrer';c.append(link);if(a.image){const provenance=el('p',null,'meta');const l=el('a','Provenienza della fotografia');l.href=a.image.sourceUrl;l.target='_blank';l.rel='noopener noreferrer';provenance.append(l);c.append(provenance)}}else c.append(el('p','Nessuna fonte: scheda esemplificativa senza notizie reali.','meta'));const reader=$('#reader');reader.showModal();reader.scrollTop=0;document.body.classList.add('reading');if(!reducedMotion.matches){readerAnimation=reader.animate([{opacity:0,transform:'translateY(28px) scale(.98)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:300,easing:'cubic-bezier(.16,1,.3,1)'});readerAnimation.finished.catch(()=>{})}}
async function closeReader(){const reader=$('#reader');if(!reader.open||closingReader)return;closingReader=true;const computed=getComputedStyle(reader);const from={opacity:computed.opacity,transform:computed.transform};readerAnimation?.cancel();if(!reducedMotion.matches){readerAnimation=reader.animate([from,{opacity:0,transform:'translateY(28px) scale(.98)'}],{duration:180,easing:'cubic-bezier(.4,0,1,1)',fill:'forwards'});await readerAnimation.finished.catch(()=>{})}reader.close();readerAnimation?.cancel();closingReader=false;}
$('#close').onclick=closeReader;$('#reader').addEventListener('cancel',e=>{e.preventDefault();closeReader()});$('#reader').addEventListener('close',()=>{document.body.classList.remove('reading');lastFocus?.focus({preventScroll:true})});$('#saved').onclick=()=>{onlySaved=!onlySaved;render()};
async function load(){try{const r=await fetch('data/current.json',{cache:'no-store'});if(!r.ok)throw Error();const next=await r.json();if(next.schemaVersion!==1||!Array.isArray(next.articles)||!next.essentialIds||!next.leadIds||!next.compactIds)throw Error();edition=next;$('#date').textContent=(edition.mode==='demo'?'DEMO · ':'EDIZIONE · ')+date(edition.editionDate+'T12:00:00+01:00');$('.notice').hidden=edition.mode!=='demo';if(edition.mode==='live'){$('.about>p').textContent=edition.articles.length+' storie selezionate con fonti gratuite. Ogni approfondimento distingue la data di pubblicazione da quella dei fatti.';$('.dateline span:last-child').textContent='Edizione mattina';}if(edition.mode!=='demo'){$('#connection').textContent='Ultima edizione: '+date(edition.editionDate+'T12:00:00+01:00');if(edition.editionDate!==new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Rome'}).format(new Date()))$('#status').textContent='Edizione precedente: l’aggiornamento di oggi non è ancora disponibile.'}render();return true}catch{$('#status').textContent=edition?'Aggiornamento non disponibile. Resta visibile l’ultima edizione caricata.':'Impossibile caricare l’edizione. Riprova quando sei online.';return false}}
$('#refresh').onclick=async()=>{if(await load())$('#status').textContent=edition.mode==='demo'?'Demo aggiornata. Il flusso giornaliero non è collegato.':'Edizione caricata: '+date(edition.editionDate+'T12:00:00+01:00')};function connection(){$('#connection').textContent=navigator.onLine?'Connessione disponibile · la lettura offline si prepara alla prima apertura.':'Sei offline · stai leggendo l’ultima edizione disponibile su questo dispositivo.'}addEventListener('online',connection);addEventListener('offline',connection);connection();await load();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js?v=5').catch(()=>{$('#connection').textContent='Lettura offline non disponibile in questo browser.'});
